-- 7. Chat messages (sender: user / assistant)

INSERT INTO chat_messages (id, session_id, sender, body, image_url, created_at) VALUES
  ('900f2c0e-36f3-51b5-9623-948c37fb5bf9', '39dad266-dbf7-56bf-88c4-54f3e6ebb869', 'user', 'Good day. I would like to file a complaint. Residents of a walk-up flat block in Seksyen 11 report roof leaks across the top floor after heavy rain; the management corporation says the repair cost exceeds its sinking fund.', NULL, '2026-04-29 06:50:24+08'),
  ('deedb17c-d7ef-5989-b05a-967cc361ecc7', '39dad266-dbf7-56bf-88c4-54f3e6ebb869', 'assistant', 'Thank you for informing us. May I know when you first noticed the issue?', NULL, '2026-04-29 06:51:45+08'),
  ('823445e1-b936-5510-854e-4f70672b944f', '39dad266-dbf7-56bf-88c4-54f3e6ebb869', 'user', 'It started about 5 days ago.', NULL, '2026-04-29 06:52:35+08'),
  ('cb49e41c-70d8-50e7-82c6-c1d724c7263b', '39dad266-dbf7-56bf-88c4-54f3e6ebb869', 'assistant', 'Thank you. Here is a summary of your complaint: Roof leak, low-cost flats at Jalan 11/6, Seksyen 11. Please review the details and press the Confirm button to submit your report.', NULL, '2026-04-29 06:54:12+08'),
  ('d4db476e-7bb5-518e-bc4b-057572ea827f', 'e915c884-83b8-5397-95f7-d13975a4934a', 'user', 'Good day. I would like to file a complaint. A neighbour has extended a terrace house to the boundary line without approved plans on Jalan 17/21, Seksyen 17; the adjoining owner reports blocked ventilation.', NULL, '2026-02-19 22:45:27+08'),
  ('d05addda-b0a1-501e-8e98-4ce51b056e2e', 'e915c884-83b8-5397-95f7-d13975a4934a', 'assistant', 'Understood. Could you tell me when this issue started?', NULL, '2026-02-19 22:47:51+08'),
  ('9d8b2044-7af2-5a61-8865-cba306323361', 'e915c884-83b8-5397-95f7-d13975a4934a', 'user', 'It was first noticed about 3 weeks ago.', NULL, '2026-02-19 22:49:39+08'),
  ('263a2890-e138-5131-8c86-b6df52282ee1', 'e915c884-83b8-5397-95f7-d13975a4934a', 'assistant', 'Thank you. Here is a summary of your complaint: Illegal extension at Jalan 17/21, Seksyen 17. Please review the details and press the Confirm button to submit your report.', NULL, '2026-02-19 22:50:55+08'),
  ('311198cd-c867-5c38-a9dc-70baed7fec99', 'af20f631-bf80-5508-8ee9-0866fd98a914', 'user', 'Good day. I would like to file a complaint. A house on Jalan 18/13 in Seksyen 18 is used as a storage and repair workshop; residents report lorry movements at night.', NULL, '2026-09-27 08:43:52+08'),
